// The oracle of .NET's text rules that the ILSpy port copies:
//   NetText categories <file>   the Unicode category of every UTF-16 code unit, as C++ ranges (decompiler/util/char_categories.inc)
//   NetText numbers <file>      float and double values with their ToString("R") text, invariant culture (testdata/golden/numbers.txt)
using System;
using System.Globalization;
using System.IO;
using System.Text;

static class Program
{
    static void Main(string[] args)
    {
        if (args[0] == "categories") Categories(args[1]);
        else Numbers(args[1]);
    }

    static void Categories(string file)
    {
        var b = new StringBuilder();
        b.Append("// decompiler/util/char_categories.inc -- generated by testdata/oracle/NetText (\"categories\") from .NET ").Append(Environment.Version).Append(": the\n");
        b.Append("// Unicode category (System.Globalization.UnicodeCategory) of every UTF-16 code unit as {first code unit, category} runs.\n");
        int start = 0;
        var cat = CharUnicodeInfo.GetUnicodeCategory((char)0);
        for (int c = 1; c <= 0x10000; c++)
        {
            var next = c < 0x10000 ? CharUnicodeInfo.GetUnicodeCategory((char)c) : (UnicodeCategory)(-1);
            if (next != cat)
            {
                b.Append("{0x").Append(start.ToString("X4")).Append(", ").Append((int)cat).Append("},\n");
                start = c;
                cat = next;
            }
        }
        File.WriteAllText(file, b.ToString());
    }

    static void Numbers(string file)
    {
        var b = new StringBuilder();
        var inv = CultureInfo.InvariantCulture;
        var rng = new Random(20261126);
        void D(double d) => b.Append("d ").Append(BitConverter.DoubleToInt64Bits(d).ToString("x16")).Append(' ').Append(d.ToString("R", inv)).Append('\n');
        void F(float f) => b.Append("f ").Append(BitConverter.SingleToInt32Bits(f).ToString("x8")).Append(' ').Append(f.ToString("R", inv)).Append('\n');
        double[] fixedD = { 0, 1, -1, 0.1, 0.5, 1.5, 2.5, 10, 100, 1e14, 1e15, 1e16, 123456789012345, 1234567890123456, 12345678901234567, 0.0001, 0.00001,
            0.00012345, 1e-5, 1e-10, 1e300, -1e-300, double.Epsilon, double.MaxValue, double.MinValue, Math.PI, Math.E, 1.0 / 3, 2.0 / 3, 3.14159265358979,
            0.30000000000000004, 9007199254740993, 4.35, 1e21, 1e22, 123.456, 5e-324, 1.7976931348623157E+308 };
        foreach (var d in fixedD) D(d);
        float[] fixedF = { 0, 1, -1, 0.1f, 0.5f, 1.5f, 2.5f, 10, 100, 1e6f, 1e7f, 1e8f, 1e9f, 1234567, 12345678, 123456789, 0.0001f, 0.00001f, 1e-5f,
            1e-10f, 1e30f, float.Epsilon, float.MaxValue, float.MinValue, 3.14159265f, 1f / 3, 16777217, 0.3f, 4.35f };
        foreach (var f in fixedF) F(f);
        for (int i = 0; i < 4000; i++)
        {
            long bits = rng.NextInt64();
            double d = BitConverter.Int64BitsToDouble(bits);
            if (double.IsFinite(d)) D(d);
            D(Math.Round(rng.NextDouble() * Math.Pow(10, rng.Next(-8, 22)), rng.Next(0, 8)));
            int fbits = rng.Next() ^ (rng.Next(2) << 31);
            float f = BitConverter.Int32BitsToSingle(fbits);
            if (float.IsFinite(f)) F(f);
            F((float)(rng.NextDouble() * Math.Pow(10, rng.Next(-8, 12))));
        }
        File.WriteAllText(file, b.ToString());
    }
}
